file.content:
locals {
  domains = {
    qa = {
      external_domain  = "*.liftit-sandbox.com"
      internal_domain  = "*.qa-int.liftit-sandbox.com"
      internal_domain2 = "*.qa.liftit-sandbox.com"
    }
    staging = {
      external_domain  = "*.liftit-sandbox.com"
      internal_domain  = "*.staging-int.liftit-sandbox.com"
      internal_domain2 = "*.stg.liftit-sandbox.com"
    }
    prod = {
      external_domain = "*.liftit.co"
      internal_domain = "*.prod-int.liftit.co"
    }
    sha = {
      external_domain = "*.liftit.co"
      internal_domain = "*.sha-int.liftit.co"
    }
    sec = {
      external_domain = "*.liftit.co"
      internal_domain = "*.sec-int.liftit.co"
    }
    bi = {
      external_domain = "*.liftit.co"
      internal_domain = "*.bi-int.liftit.co"
    }
  }
}

module "ssl" {
  source     = "git::ssh://git@github.com/liftitapp/tf-modules.git//ssl"
  project_id = local.project_id[terraform.workspace]
  location   = "global"
  domains = concat([
    replace(local.domains[terraform.workspace].external_domain, "*.", ""),
    local.domains[terraform.workspace].external_domain,
  ], terraform.workspace == "qa" || terraform.workspace == "staging" ? [local.domains[terraform.workspace].internal_domain2] : [])
  labels = local.default_labels
}

resource "cloudflare_record" "ns" {
  count   = length(local.zone_name_servers[terraform.workspace == "bi" ? "prod" : terraform.workspace])
  zone_id = terraform.workspace == "prod" || terraform.workspace == "sha" || terraform.workspace == "sec" || terraform.workspace == "bi" ? local.hosted_zone_id : local.hosted_zone_id_lowenv
  name    = terraform.workspace == "prod" || terraform.workspace == "sha" || terraform.workspace == "sec" || terraform.workspace == "bi" ? replace(replace(local.domains[terraform.workspace].internal_domain, "*.", ""), ".liftit.co", "") : replace(replace(local.domains[terraform.workspace].internal_domain, "*.", ""), ".liftit-sandbox.com", "")
  type    = "NS"
  content = element(local.zone_name_servers[terraform.workspace == "bi" ? "prod" : terraform.workspace], count.index)
}


resource "cloudflare_record" "cname" {
  for_each = {
    for rec in module.ssl.dns_resource_record :
    rec.name => rec
  }
  zone_id         = terraform.workspace == "prod" || terraform.workspace == "sha" || terraform.workspace == "sec" || terraform.workspace == "bi" ? local.hosted_zone_id : local.hosted_zone_id_lowenv
  name            = each.value.name
  type            = "CNAME"
  content         = each.value.data
  allow_overwrite = true
  depends_on      = [module.ssl]
}

