resource "google_dns_managed_zone" "default" {
  name       = var.zone_name
  dns_name   = "${var.dns_name}."
  project    = var.project_id
  visibility = var.visibility
  labels     = var.labels
  private_visibility_config {
    networks {
      network_url = "projects/${var.project_id}/global/networks/${var.vpc_name}"
    }
  }

  # 🔹 Configura peering SOLO si el proyecto es `sec`
  dynamic "peering_config" {
    for_each = var.enable_peering ? [1] : []
    content {
      target_network {
        network_url = "projects/${var.peer_project_id}/global/networks/${var.peer_vpc_name}"
      }
    }
  }
}

# 🔹 Habilitar reglas de reenvío DNS si está activado
resource "google_dns_policy" "dns_forwarding" {
  count = var.enable_dns_forwarding ? 1 : 0

  name                      = "forward-to-sec-vpc-${var.zone_name}"
  project                   = var.project_id
  enable_inbound_forwarding = true
  enable_logging            = true

  networks {
    network_url = "projects/${var.project_id}/global/networks/${var.vpc_name}"
  }
}

# 🔹 Permitir consultas DNS desde VPCs remotas hacia `sec-shared-vpc`
resource "google_project_iam_member" "dns_peer_access" {
  count = var.enable_peering ? 1 : 0

  project = var.peer_project_id
  role    = "roles/dns.peer"
  member  = "serviceAccount:${var.peering_service_account}"
}

