  description = "ID del proyecto donde se crea la zona"
  type        = string
}

variable "vpc_name" {
  description = "Nombre de la VPC donde se crea la zona"
  type        = string
}

variable "enable_peering" {
  description = "Si es true, habilita peering con `sec`"
  type        = bool
  default     = false
}

