  description = "ID del proyecto `sec` que recibe el peering"
  type        = string
  default     = ""
}

variable "peer_vpc_name" {
  description = "Nombre de la VPC en `sec`"
  type        = string
  default     = ""
}

variable "enable_dns_forwarding" {
  description = "Si es true, habilita reglas de reenvío DNS"
  type        = bool
  default     = false
}

variable "peering_service_account" {
  description = "Cuenta de servicio usada para las consultas DNS entre VPCs"
  type        = string
  default     = ""
}
variable "labels" {
  description = "Etiquetas para la zona DNS"
  type        = map(string)
}
variable "visibility" {
  description = "Visibilidad de la zona DNS"
  type        = string
  default     = "public"
}

