locals {
  services = {
    cloud-storage = [
      "roles/storage.admin",
      "roles/cloudkms.cryptoKeyEncrypterDecrypter"
    ]
    compute-engine = [
      "roles/compute.admin",
      "roles/container.defaultNodeServiceAccount",
      "roles/cloudkms.cryptoKeyEncrypterDecrypter",
      "roles/logging.admin",
      "roles/logging.logWriter",
      "roles/monitoring.metricWriter"
    ]
    bigquery = [
      "roles/bigquery.admin",
      "roles/cloudkms.cryptoKeyEncrypterDecrypter"
    ]
    pubsub = [
      "roles/pubsub.admin",
      "roles/cloudkms.cryptoKeyEncrypterDecrypter"
    ]
    kubernetes-engine = [
      "roles/container.admin",
      "roles/cloudkms.cryptoKeyEncrypterDecrypter",
      "roles/logging.admin"
    ]
    cloud-run = [
      "roles/run.admin",
      "roles/cloudkms.cryptoKeyEncrypterDecrypter",
      "roles/logging.admin",
    ]
    cloud-functions = [
      "roles/cloudfunctions.admin",
      "roles/cloudkms.cryptoKeyEncrypterDecrypter",
      "roles/logging.admin",
    ]
  }

  permissions_sec_account = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
  permissions_sha_account = "roles/artifactregistry.reader"

}

module "kms-permissions" {
  # Crea las cuentas de servicio personalizadas para cada proyecto
  for_each     = local.services
  source       = "git::ssh://git@github.com/liftitapp/tf-modules.git//service-account"
  project_id   = local.project_id[terraform.workspace]
  account_id   = each.key
  display_name = "Service Account para uso de kms en el proyecto de sec"
  roles_app    = local.services[each.key]
}

resource "google_project_iam_member" "kms-account-permissions" {
  # Sirve para que las cuentas de servicio creadas en cada proyecto puedan acceder a KMS en el proyecto sec
  for_each = local.services
  project  = local.project_id.sec
  role     = local.permissions_sec_account
  member   = "serviceAccount:${module.kms-permissions[each.key].service_account_email}"
  depends_on = [
    module.kms-permissions
  ]
}
resource "google_project_iam_member" "artifact-registry-account-gke" {
  project = local.project_id.sha
  role    = local.permissions_sha_account
  member  = "serviceAccount:${module.kms-permissions["compute-engine"].service_account_email}"
  depends_on = [
    module.kms-permissions
  ]
}
resource "google_project_iam_member" "kms-sa-default-artifact-registry" {
  # Sirve para que la cuenta default del servicio de Artifact Registry en el proyecto shared pueda acceder a KMS en el proyecto sec
  count   = terraform.workspace == "sha" ? 1 : 0
  project = local.project_id.sec
  role    = local.permissions_sec_account
  member  = "serviceAccount:service-${local.project_numbers["shared"]}@gcp-sa-artifactregistry.iam.gserviceaccount.com"
  depends_on = [
    module.kms-permissions
  ]
}

resource "google_project_iam_member" "kms-sa-disks" {
  # Sirve para que la cuenta default del servicio de Compute Engine en cada proyecto pueda acceder a KMS en el proyecto sec
  project = local.project_id.sec
  role    = local.permissions_sec_account
  member  = terraform.workspace != "sec" ? (terraform.workspace != "sha" ? "serviceAccount:service-${local.project_numbers[terraform.workspace]}@compute-system.iam.gserviceaccount.com" : "serviceAccount:service-${local.project_numbers["shared"]}@compute-system.iam.gserviceaccount.com") : "serviceAccount:service-${local.project_numbers["security"]}@compute-system.iam.gserviceaccount.com"
  depends_on = [
    module.kms-permissions
  ]
}

resource "google_project_iam_member" "kms-secrets-manager" {
  # Sirve para que la cuenta default del servicio de secrets-manager en cada proyecto pueda acceder a KMS en el proyecto sec
  project = local.project_id.sec
  role    = local.permissions_sec_account
  member  = terraform.workspace != "sec" ? (terraform.workspace != "sha" ? "serviceAccount:service-${local.project_numbers[terraform.workspace]}@gcp-sa-secretmanager.iam.gserviceaccount.com" : "serviceAccount:service-${local.project_numbers["shared"]}@gcp-sa-secretmanager.iam.gserviceaccount.com") : "serviceAccount:service-${local.project_numbers["security"]}@gcp-sa-secretmanager.iam.gserviceaccount.com"
  depends_on = [
    module.kms-permissions
  ]
}

resource "google_project_iam_member" "artifact-registry-account-permissions" {
  # Sirve para que la cuenta default del servicio de Cloudrun, Cloud Functions y Compute Engine en cada proyecto pueda acceder a Artifact Registry en el proyecto shared
  project = local.project_id.sha
  role    = local.permissions_sha_account
  member  = terraform.workspace != "sec" ? (terraform.workspace != "sha" ? "serviceAccount:service-${local.project_numbers[terraform.workspace]}@serverless-robot-prod.iam.gserviceaccount.com" : "serviceAccount:service-${local.project_numbers["shared"]}@serverless-robot-prod.iam.gserviceaccount.com") : "serviceAccount:service-${local.project_numbers["security"]}@serverless-robot-prod.iam.gserviceaccount.com"
  depends_on = [
    module.kms-permissions
  ]
}

resource "google_project_iam_member" "secrets-manager-account-permissions" {
  # Sirve para que la cuenta default del servicio de Cloudrun, Cloud Functions y Compute Engine en cada proyecto pueda acceder a Secret Manager en su propio proyecto
  project = local.project_id[terraform.workspace]
  role    = "roles/secretmanager.secretAccessor"
  member  = terraform.workspace != "sec" ? (terraform.workspace != "sha" ? "serviceAccount:${local.project_numbers[terraform.workspace]}-compute@developer.gserviceaccount.com" : "serviceAccount:${local.project_numbers["shared"]}-compute@developer.gserviceaccount.com") : "serviceAccount:${local.project_numbers["security"]}-compute@developer.gserviceaccount.com"
  depends_on = [
    module.kms-permissions
  ]
}

resource "google_project_iam_member" "vpc-access-permissions" {
  # Sirve para que la cuenta default del servicio de Cloudrun, Cloud Functions y Compute Engine en cada proyecto pueda acceder a la VPC en su propio proyecto
  project = local.project_id[terraform.workspace]
  role    = "roles/vpcaccess.user"
  member  = terraform.workspace != "sec" ? (terraform.workspace != "sha" ? "serviceAccount:${local.project_numbers[terraform.workspace]}-compute@developer.gserviceaccount.com" : "serviceAccount:${local.project_numbers["shared"]}-compute@developer.gserviceaccount.com") : "serviceAccount:${local.project_numbers["security"]}-compute@developer.gserviceaccount.com"
  depends_on = [
    module.kms-permissions
  ]
}

resource "google_project_iam_member" "vpc-access-permissions-bi-prod" {
  # Sirve para que la cuenta default del servicio de Cloudrun, Cloud Functions y Compute Engine en liftit-bi pueda acceder a la VPC de prod
  count= terraform.workspace == "bi" ? 1 : 0
  project = local.project_id["prod"]
  role    = "roles/vpcaccess.user"
  member  = "serviceAccount:service-${local.project_numbers["bi"]}@serverless-robot-prod.iam.gserviceaccount.com"
  depends_on = [
    module.kms-permissions
  ]
}

resource "google_project_iam_member" "compute-network-user-permissions" {
  # Sirve para que la cuenta default del servicio de Cloudrun, Cloud Functions y Compute Engine en cada proyecto pueda acceder a la red en su propio proyecto
  project = local.project_id[terraform.workspace]
  role    = "roles/compute.networkUser"
  member  = terraform.workspace != "sec" ? (terraform.workspace != "sha" ? "serviceAccount:${local.project_numbers[terraform.workspace]}-compute@developer.gserviceaccount.com" : "serviceAccount:${local.project_numbers["shared"]}-compute@developer.gserviceaccount.com") : "serviceAccount:${local.project_numbers["security"]}-compute@developer.gserviceaccount.com"
  depends_on = [
    module.kms-permissions
  ]
}

resource "google_project_iam_member" "cloud-storage-account-permissions" {
  # Sirve para que la cuenta default del servicio de Cloud Storage en cada proyecto pueda acceder a KMS en el proyecto sec
  project = local.project_id.sec
  role    = local.permissions_sec_account
  member  = terraform.workspace != "sec" ? (terraform.workspace != "sha" ? "serviceAccount:service-${local.project_numbers[terraform.workspace]}@gs-project-accounts.iam.gserviceaccount.com" : "serviceAccount:service-${local.project_numbers["shared"]}@gs-project-accounts.iam.gserviceaccount.com") : "serviceAccount:service-${local.project_numbers["security"]}@gs-project-accounts.iam.gserviceaccount.com"
  depends_on = [
    module.kms-permissions
  ]
}

resource "google_project_iam_member" "logging-permissions" {
  # Sirve para que la cuenta default del servicio de  Compute Engine en cada proyecto pueda acceder a escribir logs en su propio proyecto
  project = local.project_id[terraform.workspace]
  role    = "roles/logging.admin"
  member  = terraform.workspace != "sec" ? (terraform.workspace != "sha" ? "serviceAccount:${local.project_numbers[terraform.workspace]}-compute@developer.gserviceaccount.com" : "serviceAccount:${local.project_numbers["shared"]}-compute@developer.gserviceaccount.com") : "serviceAccount:${local.project_numbers["security"]}-compute@developer.gserviceaccount.com"
  depends_on = [
    module.kms-permissions
  ]
}

