    "lms-tracking",
    "lms-root-app",
    "backoffice-v2",
    "liftit-tracking",
  ], terraform.workspace == "prod" ? ["liftit-website"] : [])
  cors_origins     = terraform.workspace == "prod" ? ["https://lms.liftit.co", "https://tms.liftit.co", "https://lms-tracking.liftit.co", "http://localhost:4001"] : ["https://lms-${terraform.workspace == "staging" ? replace(terraform.workspace, "staging", "stg") : terraform.workspace}.liftit-sandbox.com", "https://tms-${terraform.workspace == "staging" ? replace(terraform.workspace, "staging", "stg") : terraform.workspace}.liftit-sandbox.com", "https://tms.${terraform.workspace == "staging" ? replace(terraform.workspace, "staging", "stg") : terraform.workspace}.liftit-sandbox.com", "https://lms-tracking-${terraform.workspace == "staging" ? replace(terraform.workspace, "staging", "stg") : terraform.workspace}.liftit-sandbox.com", terraform.workspace == "qa" ? "https://lms-tracking-root-qa.liftit-sandbox.com" : "https://lms-tracking-${terraform.workspace == "staging" ? replace(terraform.workspace, "staging", "stg") : terraform.workspace}.liftit-sandbox.com", "http://localhost:4001"]
  excluded         = ["liftit-co"]
  filtered_buckets = tolist(setsubtract(local.buckets, local.excluded))
}

# Ojo en los otros ambientes con el bucket de lms-tracking y lms-root-app ejecutar gsutil web set -m index.html -e 404.html gs://lms-tracking-${ambiente
module "frontends-gcs" {
  for_each                 = toset(local.buckets)
  source                   = "git::ssh://git@github.com/liftitapp/tf-modules.git//cloud-storage"
  bucket_name              = "${each.value}-${terraform.workspace}"
  location                 = "us-east1"
  versioning_enabled       = false
  public_access            = true
  enable_cors              = true
  cors_origins             = local.cors_origins
  cors_methods             = ["GET"]
  enable_website           = true
  website_main_page_suffix = "index.html"
  website_not_found_page   = "index.html"
}

