content.content:
  1→resource "google_compute_address" "static_ip" {
  2→  count  = var.static_ip ? 1 : 0
  3→  name   = "${var.name}-static-ip"
  4→  region = join("-", slice(split("-", var.zone), 0, 2))
  5→}
  6→
  7→resource "google_compute_disk" "boot_disk" {
  8→  count = var.existing_boot_disk == "" && (var.image == null || var.image == "") ? 1 : 0
  9→  name  = "${var.name}-boot-disk"
 10→  type  = var.boot_disk_type
 11→  size  = var.boot_disk_size
 12→  zone  = var.zone
 13→
 14→  # Si usa snapshot
 15→  snapshot = var.snapshot != "" ? var.snapshot : null
 16→
 17→  disk_encryption_key {
 18→    kms_key_self_link = var.encryption_key == "" ? null : var.encryption_key
 19→  }
 20→}
 21→
 22→resource "google_compute_disk_resource_policy_attachment" "attach_backup_boot" {
 23→  count = var.existing_boot_disk == "" && (var.image == null || var.image == "") ? 1 : 0
 24→
 25→  name = var.backup_policy != "" ? var.backup_policy : google_compute_resource_policy.backup_policy[0].name
 26→  disk = google_compute_disk.boot_disk[0].name
 27→  zone = var.zone
 28→}
 29→
 30→resource "google_compute_instance" "vm" {
 31→  name                = var.name
 32→  machine_type        = var.machine_type
 33→  zone                = var.zone
 34→  tags                = var.network_tags
 35→  labels              = var.labels
 36→  enable_display      = false
 37→  deletion_protection = var.enable_deletion_protection
 38→  can_ip_forward      = var.enable_ip_forwarding
 39→
 40→  boot_disk {
 41→    dynamic "initialize_params" {
 42→      for_each = var.existing_boot_disk == "" && var.snapshot == "" ? [1] : []
 43→      content {
 44→        image = var.image != "" ? var.image : null
 45→        type  = var.boot_disk_type
 46→        size  = var.boot_disk_size
 47→      }
 48→    }
 49→    source            = var.existing_boot_disk != "" ? var.existing_boot_disk : (var.image == null || var.image == "" ? google_compute_disk.boot_disk[0].self_link : null)
 50→    kms_key_self_link = var.encryption_key
 51→  }
 52→
 53→  dynamic "network_interface" {
 54→    for_each = var.network_interfaces
 55→    content {
 56→      network    = network_interface.value.network
 57→      subnetwork = network_interface.value.subnetwork
 58→      dynamic "access_config" {
 59→        for_each = var.static_ip || var.assign_public_ip || lookup(network_interface.value, "nat_ip", null) != null ? [1] : []
 60→        content {
 61→          nat_ip = var.static_ip ? google_compute_address.static_ip[0].address : lookup(network_interface.value, "nat_ip", null)
 62→        }
 63→      }
 64→    }
 65→  }
 66→
 67→  service_account {
 68→    email  = var.service_account
 69→    scopes = var.service_account_scopes
 70→  }
 71→
 72→  dynamic "attached_disk" {
 73→    for_each = google_compute_disk.additional
 74→    content {
 75→      source = attached_disk.value.self_link
 76→    }
 77→  }
 78→  lifecycle {
 79→    ignore_changes = [
 80→      boot_disk[0].kms_key_self_link,
 81→    ]
 82→  }
 83→}
 84→
 85→resource "google_compute_disk" "additional" {
 86→  for_each = { for idx, disk in var.additional_disks : idx => disk }
 87→
 88→  name     = each.value.name
 89→  size     = each.value.size
 90→  type     = each.value.type
 91→  zone     = var.zone
 92→  snapshot = lookup(each.value, "snapshot", null)
 93→  disk_encryption_key {
 94→    kms_key_self_link = lookup(each.value, "encryption_key", null)
 95→  }
 96→}
 97→
 98→resource "google_compute_resource_policy" "backup_policy" {
 99→  count  = var.backup_policy == "" ? 1 : 0
100→  name   = "${var.name}-backup-policy"
101→  region = join("-", slice(split("-", var.zone), 0, 2))
102→
103→  snapshot_schedule_policy {
104→    schedule {
105→      daily_schedule {
106→        days_in_cycle = var.backup_days_in_cycle
107→        start_time    = var.backup_start_time
108→      }
109→    }
110→
111→    retention_policy {
112→      max_retention_days    = var.backup_retention_days
113→      on_source_disk_delete = "KEEP_AUTO_SNAPSHOTS" # Opcional: Puedes cambiarlo a "APPLY_RETENTION_POLICY"
114→    }
115→  }
116→}
117→
118→resource "google_compute_disk_resource_policy_attachment" "boot_attach_backup" {
119→  count = var.existing_boot_disk == "" && (var.image == null || var.image == "") ? 1 : 0
120→
121→  name = var.backup_policy != "" ? var.backup_policy : google_compute_resource_policy.backup_policy[0].id
122→  disk = google_compute_disk.boot_disk[count.index].name
123→  zone = var.zone
124→}
125→resource "google_compute_disk_resource_policy_attachment" "attach_backup" {
126→  for_each = { for idx, disk in var.additional_disks : idx => disk }
127→  name     = var.backup_policy != "" ? var.backup_policy : google_compute_resource_policy.backup_policy[0].id
128→  disk     = google_compute_disk.additional[each.key].name
129→  zone     = var.zone
130→}
131→
132→resource "google_monitoring_notification_channel" "email_channel" {
133→  count        = var.enable_alerting ? 1 : 0
134→  display_name = "Email Alert"
135→  type         = "email"
136→
137→  labels = {
138→    email_address = var.alert_email
139→  }
140→}
141→resource "google_monitoring_alert_policy" "vm_down_alert" {
142→  count        = var.enable_alerting ? 1 : 0
143→  display_name = "VM Failure Alert"
144→  combiner     = "OR"
145→
146→  conditions {
147→    display_name = "VM Uptime Check"
148→    condition_threshold {
149→      filter          = "metric.type=\"compute.googleapis.com/instance/uptime\" AND resource.type=\"gce_instance\""
150→      comparison      = "COMPARISON_LT"
151→      threshold_value = 60     # Si la VM tiene menos de 60 segundos de uptime
152→      duration        = "300s" # Espera 5 minutos antes de activar la alerta
153→
154→      aggregations {
155→        alignment_period   = "60s"
156→        per_series_aligner = "ALIGN_MEAN"
157→      }
158→    }
159→  }
160→
161→  notification_channels = [google_monitoring_notification_channel.email_channel[0].id]
162→}
163→
164→resource "google_compute_instance_group" "fw_instance_group" {
165→  count     = var.create_instance_group ? 1 : 0
166→  name      = "${var.name}-ig"
167→  zone      = var.zone
168→  instances = [google_compute_instance.vm.id]
169→
170→  named_port {
171→    name = "http"
172→    port = var.app_port
173→  }
174→
175→  depends_on = [google_compute_instance.vm]
176→}
177→

